func NewStackQueue() *StackQueue {
    return &StackQueue{
        items: []int{},
        spare: []int{},
    }
}

func (s *StackQueue) push(x int) {
    if len(s.items) == 0 {
        s.front = x
        s.hasFront = true
    }
    s.items = append(s.items, x)
}

func (s *StackQueue) pop() int {
    for len(s.items) > 1 {
        last := len(s.items) - 1
        s.spare = append(s.spare, s.items[last])
        s.items = s.items[:last]
    }

    value := s.items[0]
    s.items = s.items[:0]

    for len(s.spare) > 0 {
        last := len(s.spare) - 1
        s.items = append(s.items, s.spare[last])
        s.spare = s.spare[:last]
    }

    if len(s.items) == 0 {
        s.hasFront = false
    } else {
        s.front = s.items[0]
    }

    return value
}

func (s *StackQueue) peek() int {
    return s.front
}

func (s *StackQueue) isEmpty() bool {
    return !s.hasFront
}
